function assetWalletEntries(symbol, balanceId, featureRows = [33, 36]) {
  const sym = symbol;
  const rows = featureRows;
  return [
    entry({ id: `wallet.asset.${sym}.balance`, featureRow: rows[0], featureName: 'Stablecoin Management · Balance display', label: `${sym} balance`, selector: `#${balanceId}`, screen: SCREEN.wallet, what: `${sym} token balance (display units + ticker).`, frontend: `#${balanceId} text; privacy blur via .balance-amount.hidden`, backend: `balances.accounts[] where symbol=${sym}`, example: { symbol: sym, amount: sym === 'hUSD' ? '2500.00' : sym === 'hEUR' ? '1250.00' : '425.50', fiatCad: sym === 'hUSD' ? 2500 : 1250 } }),
    entry({ id: `wallet.asset.${sym}.fiat`, featureRow: rows[0], featureName: 'Stablecoin Management · Balance display', label: `${sym} fiat equivalent`, selector: `[data-asset="${sym}"] .portfolio-asset-row-fiat`, screen: SCREEN.wallet, what: 'Fiat equivalent + cross-rate hint.', frontend: 'Computed from FX service', backend: 'balances.accounts[].fiat + fxRate', example: { fiatCad: 2500, fiatUsd: 1850 } }),
    entry({ id: `wallet.asset.${sym}.change7d`, featureRow: rows[1], featureName: 'Stablecoin Management · Visual summaries', label: `${sym} 7d change`, selector: `[data-asset="${sym}"] .balance-change`, screen: SCREEN.wallet, what: '7-day balance delta for asset row.', frontend: 'data-tooltip native + --fin-up styling', backend: 'GET /api/wallet/balances?includeChange=7d', example: { changePct7d: 2.5 } }),
    entry({ id: `wallet.asset.${sym}.allocationPct`, featureRow: rows[1], featureName: 'Stablecoin Management · Visual summaries', label: `${sym} allocation %`, selector: `[data-asset="${sym}"] .portfolio-asset-row-pct`, screen: SCREEN.wallet, what: 'Percent of total portfolio in this asset.', frontend: 'amount / portfolioTotal * 100', backend: 'Server-calculated allocationPct', example: { allocationPct: 30.3 } }),
    entry({ id: `wallet.asset.${sym}.sendAction`, featureRow: 35, featureName: 'Stablecoin Management · Quick actions', label: `${sym} Send CTA`, selector: `[data-asset="${sym}"] a[href*="send-enhanced"]`, screen: SCREEN.wallet, what: 'Per-asset Send CTA — deep link to remittance with asset query.', frontend: `send-enhanced.html?asset=${sym}`, backend: 'N/A', seeAlso: ['send.method.external'] }),
  ];
}

