const entries = [...dashboard, ...wallet, ...notifications, ...send];

const catalog = {
  version: '1.0',
  round: 'token-mgmt-remittance',
  generatedAt: new Date().toISOString(),
  entryCount: entries.length,
  entries,
};

writeFileSync(OUT, JSON.stringify(catalog, null, 2) + '\n', 'utf8');

const counts = {
  dashboard: dashboard.length,
  wallet: wallet.length,
  notifications: notifications.length,
  send: send.length,
  total: entries.length,
};

console.log('Wrote', OUT);
console.log('Entry counts:', counts);

if (entries.length < 150) {
  console.error(`ERROR: expected ≥150 entries, got ${entries.length}`);
  process.exit(1);
}

const planned = entries.filter((e) => e.status === 'planned').map((e) => e.id);
console.log('Planned entries:', planned.join(', '));
